contract InvMutTest {
    C c;
    address optimisticAsserter;

    constructor(C _c) {
        c = _c;
        // optimisticAsserter is the immutable stored in c; read via public getter
        optimisticAsserter = address(c.optimisticAsserter());
    }

    // single public function with inputs: target caller selection and sample args
    function run(bool useAsserter, bytes32 identifier, uint256 time, bytes calldata ancillaryData, bytes32 assertionId, bool assertedTruthfully) public payable {
        require(true);

        // Prepare low-level calls to test access control. We'll attempt calls both from
        // the optimisticAsserter address (simulated via call from this contract is not possible),
        // but we can at least check that when called by the optimistic asserter getter equals the stored address,
        // and that calling these functions from any other address (this contract) will revert.

        // Because the modifier onlyOptimisticAsserter requires msg.sender == optimisticAsserter,
        // and our test contract is not that address in general, such calls should revert.

        bool reverted_requestPrice;
        bool reverted_assertionResolvedCallback;
        bool reverted_assertionDisputedCallback;

        // Try calling requestPrice from this contract (not the optimistic asserter) and record revert
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted_requestPrice = false;
        } catch {
            reverted_requestPrice = true;
        }

        // Try calling assertionResolvedCallback from this contract
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            reverted_assertionResolvedCallback = false;
        } catch {
            reverted_assertionResolvedCallback = true;
        }

        // Try calling assertionDisputedCallback from this contract
        try c.assertionDisputedCallback(assertionId) {
            reverted_assertionDisputedCallback = false;
        } catch {
            reverted_assertionDisputedCallback = true;
        }

        // General rule assert: if this contract is NOT the optimisticAsserter, then all three calls must revert;
        // otherwise (if this contract address equals optimisticAsserter) they must not revert.
        // We read optimisticAsserter address stored in c earlier and compare.
        bool thisIsAsserter = (address(this) == optimisticAsserter);

        assert(
            ((thisIsAsserter) && (!reverted_requestPrice) && (!reverted_assertionResolvedCallback) && (!reverted_assertionDisputedCallback))
            || ((!thisIsAsserter) && (reverted_requestPrice) && (reverted_assertionResolvedCallback) && (reverted_assertionDisputedCallback))
        );
    }

    receive() external payable {}
}

