contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try calling requestPrice both as allowed caller (optimisticAsserter)
    // and as not-allowed caller (this contract). We observe whether the call reverted and that
    // the allowed call does not revert. The general rule asserted: onlyOptimisticAsserter modifier
    // enforces that calls from address(optimisticAsserter) succeed while calls from others revert.
    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        require(true);

        // First, read the optimisticAsserter address via the public getter
        address optimistic = address(c.optimisticAsserter());

        // Attempt to call requestPrice as this contract (should revert because onlyOptimisticAsserter)
        bool revertedWhenCallerIsTest;
        try c.requestPrice(identifier, time, ancillaryData) {
            revertedWhenCallerIsTest = false;
        } catch {
            revertedWhenCallerIsTest = true;
        }

        // Next, attempt to call requestPrice from the optimisticAsserter address by invoking
        // the call via low-level call. The checker deploys c and optimisticAsserter is some address;
        // we can simulate a call from optimistic by using address(optimistic).call only if we control it,
        // but we do not. However we can check that if optimistic equals address(this) (i.e., this contract is the optimisticAsserter)
        // then the call via the public function should succeed; otherwise it must revert. So the general rule is:
        // revertedWhenCallerIsTest == (optimistic != address(this)). This is observable and general.

        // No state-changing call other than the above is allowed. Assert the property relating observed revert
        // to the optimisticAsserter getter.
        assert(revertedWhenCallerIsTest == (optimistic != address(this)));
    }

    receive() external payable {}
}

