contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry that will be executed with arbitrary inputs
    function run(address caller, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        // require that caller is not the zero address to avoid ambiguous behaviors
        require(caller != address(0));

        // We will attempt three calls that are protected by onlyOptimisticAsserter modifier.
        // Because onlyOptimisticAsserter checks msg.sender == address(optimisticAsserter),
        // the call should revert unless msg.sender equals that stored address.
        // Since the test contract is the deployer and InvMutTest is the msg.sender for calls to c,
        // we check behavior for both: when caller equals optimisticAsserter and when not.

        // Read the optimisticAsserter address from c via its public getter
        address optimisticAddr = address(c.optimisticAsserter());

        // We'll perform each call twice: once as this contract (msg.sender==address(this))
        // and once by forwarding via a call from an EOA address is not possible here.
        // Instead, we use the provided `caller` parameter to compare with optimisticAsserter.
        // The rule: if caller equals optimisticAsserter then a direct call from this contract
        // is considered authorized only if address(this) == optimisticAsserter. Since that's unlikely,
        // we assert the general relation that only when address(this) == optimisticAsserter the calls do not revert.

        // Attempt requestPrice and detect revert
        bool reqReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        // Attempt assertionResolvedCallback and detect revert
        bool resReverted;
        try c.assertionResolvedCallback(bytes32(0), true) {
            resReverted = false;
        } catch {
            resReverted = true;
        }

        // Attempt assertionDisputedCallback and detect revert
        bool disReverted;
        try c.assertionDisputedCallback(bytes32(0)) {
            disReverted = false;
        } catch {
            disReverted = true;
        }

        // Read c's optimisticAsserter again and balance to include in the assertion
        address optAfter = address(c.optimisticAsserter());
        uint256 cBal = address(c).balance;

        // General rule (single assert): For this contract's calls, none of the three protected
        // functions may succeed unless this contract is exactly the optimisticAsserter stored in c.
        // Additionally, the optimisticAsserter getter must be stable and equal to the earlier read.
        // Finally, if requestPrice did not revert, the contract must have emitted the PriceRequestAdded
        // event — we cannot observe events here, so we instead require that non-reversion implies the optimistic
        // asserter address equals address(this). This encodes the only-asserter authorization property.
        assert(optAfter == optimisticAddr && (
            (address(this) == optimisticAddr && !reqReverted && !resReverted && !disReverted) ||
            (address(this) != optimisticAddr && reqReverted && resReverted && disReverted)
        ));
    }

    // allow receiving Ether if needed
    receive() external payable {}
}

