    // Single public entry: try the three onlyOptimisticAsserter-protected calls and assert the authorization property.
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        // No special preconditions on parameters
        require(true);

        // Read the optimisticAsserter address before any calls
        address optBefore = address(c.optimisticAsserter());

        // Attempt requestPrice and detect revert
        bool reqReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        // Attempt assertionResolvedCallback and detect revert
        bool resReverted;
        try c.assertionResolvedCallback(bytes32(0), true) {
            resReverted = false;
        } catch {
            resReverted = true;
        }

        // Attempt assertionDisputedCallback and detect revert
        bool disReverted;
        try c.assertionDisputedCallback(bytes32(0)) {
            disReverted = false;
        } catch {
            disReverted = true;
        }

        // Read the optimisticAsserter address after the calls to ensure it is stable
        address optAfter = address(c.optimisticAsserter());

        // The property to hold for all inputs and states reachable: the getter is stable,
