contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that tests that requestPrice only accepts calls from optimisticAsserter
    // We model the optimistic asserter by calling requestPrice directly from this contract, which
    // will revert because onlyOptimisticAsserter enforces msg.sender==address(optimisticAsserter).
    // The general rule we assert: if the caller is not the configured optimisticAsserter, requestPrice reverts
    // and does not change address(c).balance. We observe revert and balance.

    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);

        // record balance before
        uint256 balBefore = address(c).balance;

        bool reverted;
        // call that is expected to revert because msg.sender (this contract) is not optimisticAsserter
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;

        // Assert the general rule: if caller is not the optimisticAsserter then requestPrice reverts and balance unchanged.
        // We observe msg.sender != address(optimisticAsserter) by reading optimisticAsserter getter and comparing to address(this).
        address opt = address(c).optimisticAsserter();
        assert((opt != address(this) && reverted && balAfter == balBefore) || (opt == address(this) && !reverted));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The single public entry that encodes the property described above.
    // We cannot directly read c.optimisticAsserter() because optimisticAsserter is a public variable of type OptimisticAsserterInterface
    // (not address) so the auto-generated getter on C is optimisticAsserter(), which returns OptimisticAsserterInterface.
    // Access it by calling c.optimisticAsserter() and converting to address.

    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);

        // balance before call
        uint256 balBefore = address(c).balance;

        bool reverted;
        // perform the call and observe whether it reverts
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;

        // read the optimisticAsserter stored in c via its public getter and convert to address
        address optAddr = address(c.optimisticAsserter());

        // General rule asserted:
        // If the optimisticAsserter is not this contract, then the call must have reverted and c's balance must be unchanged.
        // If the optimisticAsserter is this contract, then the call must not have reverted.
        assert((optAddr != address(this) && reverted && balAfter == balBefore) || (optAddr == address(this) && !reverted));
    }

    receive() external payable {}
