contract InvMutTest {
    C c;
    address payable senderExternal;
    constructor(C _c) { c = _c; senderExternal = payable(address(0x1234)); }

    // single public entry for property-based test
    function run(address caller, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        // caller will be used to simulate optimisticAsserter; require it's not zero to be meaningful
        require(caller != address(0), "caller nonzero");

        // Read the optimisticAsserter() public immutable getter
        address optimistic = address(c.optimisticAsserter());

        // If caller equals optimistic, the three functions must NOT revert and requestPrice should emit
        // We cannot capture events here, but we can ensure calls do not revert when called from optimistic

        bool revertedRequestWhenOptimistic = true;
        bool revertedResolvedWhenOptimistic = true;
        bool revertedDisputedWhenOptimistic = true;

        bool revertedRequestWhenOther = true;
        bool revertedResolvedWhenOther = true;
        bool revertedDisputedWhenOther = true;

        // Call as optimistic by making the test contract act as optimistic: only possible if caller equals optimistic
        // The checker deploys c and then calls run; we simulate two cases depending on equality

        if (caller == optimistic) {
            // invoking these functions as the optimistic asserter should succeed (not revert)
            // Because c's functions are external, msg.sender must equal optimistic; here msg.sender is this contract,
            // but the rule we assert is about which address is allowed — we can observe optimistic address and check behavior when optimistic != address(this)
            // However, we can actually test behavior by invoking directly and observing revert; the required property: if this contract matches optimistic, calls don't revert.
            if (address(this) == optimistic) {
                // Try requestPrice
                try c.requestPrice(identifier, time, ancillaryData) {
                    revertedRequestWhenOptimistic = false;
                } catch {
                    revertedRequestWhenOptimistic = true;
                }

                // Try assertionResolvedCallback
                try c.assertionResolvedCallback(bytes32(0xdead), true) {
                    revertedResolvedWhenOptimistic = false;
                } catch {
                    revertedResolvedWhenOptimistic = true;
                }

                // Try assertionDisputedCallback
                try c.assertionDisputedCallback(bytes32(0xbeef)) {
                    revertedDisputedWhenOptimistic = false;
                } catch {
                    revertedDisputedWhenOptimistic = true;
                }
            } else {
                // If caller == optimistic but this contract is not that address, we cannot impersonate; in that case we only assert that non-optimistic callers revert
                revertedRequestWhenOptimistic = true;
                revertedResolvedWhenOptimistic = true;
                revertedDisputedWhenOptimistic = true;
            }
        }

        // Now attempt calls from a non-optimistic caller (this contract) if optimistic != address(this)
        if (optimistic != address(this)) {
            try c.requestPrice(identifier, time, ancillaryData) {
                revertedRequestWhenOther = false;
            } catch {
                revertedRequestWhenOther = true;
            }

            try c.assertionResolvedCallback(bytes32(0xabc), false) {
                revertedResolvedWhenOther = false;
            } catch {
                revertedResolvedWhenOther = true;
            }

            try c.assertionDisputedCallback(bytes32(0xdef)) {
                revertedDisputedWhenOther = false;
            } catch {
                revertedDisputedWhenOther = true;
            }
        } else {
            // If optimistic equals this contract, then non-optimistic-case flags are not meaningful
            revertedRequestWhenOther = false;
            revertedResolvedWhenOther = false;
            revertedDisputedWhenOther = false;
        }

        // General rule to assert:
        // - If this contract is the optimistic asserter, its calls MUST NOT revert.
        // - If this contract is NOT the optimistic asserter, those calls MUST revert.
        // We express that by relating optimistic == address(this) to revert flags for the three functions.
        assert(
            ((address(this) == optimistic) && !revertedRequestWhenOptimistic && !revertedResolvedWhenOptimistic && !revertedDisputedWhenOptimistic)
            || ((address(this) != optimistic) && revertedRequestWhenOther && revertedResolvedWhenOther && revertedDisputedWhenOther)
        );
    }

    receive() external payable {}
}

