    constructor(C _c) { c = _c; }

    // single public function with inputs; not payable because we don't send ETH
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public {
        // observe optimisticAsserter via public getter
        address optimistic = address(c.optimisticAsserter());

        // perform the state-changing call directly as required: top-level call on c
        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call succeeds iff optimisticAsserter() == address(this)
        assert((optimistic == address(this)) == (!reverted));
    }

    receive() external payable {}
}

