contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // run tests with arbitrary callerAddress flag and arbitrary input to requestPrice
    // callerIsAsserter: when true, we simulate that this contract is the optimisticAsserter by
    // deploying c with optimisticAsserter = address(this) in the harness. The checker will deploy c
    // fresh for each run; so the test only needs to call requestPrice and observe revert vs succeed.
    function run(bool expectAsserter, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);

        // Try calling requestPrice and record whether it reverted.
        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If this InvMutTest contract is the optimisticAsserter configured in c then onlyOptimisticAsserter
        // allows the call to succeed (not revert). Otherwise the call must revert with the modifier.
        // We can observe who optimisticAsserter is through the public getter optimisticAsserter().
        address configured = c.optimisticAsserter();

        // General rule: call succeeds (not reverted) iff configured optimisticAsserter equals this contract address.
        assert(reverted == (configured != address(this)));
    }

    receive() external payable {}
}

