contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters used to call requestPrice
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        // we will attempt to call requestPrice from this contract (which is NOT the optimisticAsserter)
        // record observable before-values
        address beforeOptimistic = address(c.optimisticAsserter());
        uint256 beforeBalance = address(c).balance;

        // perform the state-changing call and capture whether it reverted
        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, the optimisticAsserter getter and c balance must be unchanged in all cases
        // Additionally, since this contract is not the optimisticAsserter (the checker deploys c and then
        // calls run, so msg.sender here is this test contract, not c.optimisticAsserter), the call must revert.
        // However, to express a general rule that holds for all possible deployments, we assert that
        // either the call reverted OR the caller was in fact the optimisticAsserter; and always the
        // optimisticAsserter getter and contract balance are unchanged.
        assert((reverted || address(c.optimisticAsserter()) == msg.sender) &&
               address(c.optimisticAsserter()) == beforeOptimistic &&
               address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

