contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test function: tries calling three onlyOptimisticAsserter functions
    // with arbitrary inputs and asserts that either the call succeeded and msg.sender was optimisticAsserter
    // (we can observe optimisticAsserter via its public getter) or the call reverted.
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData, bytes32 assertionId, bool truth) public payable {
        // read optimisticAsserter address
        address optAddr = address(c.optimisticAsserter());

        // attempt requestPrice: onlyOptimisticAsserter should allow only optAddr, so from this contract it should revert
        bool reqReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        // attempt assertionResolvedCallback
        bool resReverted;
        try c.assertionResolvedCallback(assertionId, truth) {
            resReverted = false;
        } catch {
            resReverted = true;
        }

        // attempt assertionDisputedCallback
        bool disReverted;
        try c.assertionDisputedCallback(assertionId) {
            disReverted = false;
        } catch {
            disReverted = true;
        }

        // The general rule: if the optimisticAsserter getter is not this contract, then all three calls must have reverted.
        // If optimisticAsserter equals this contract's address (unlikely in normal deployment but possible in test harness),
        // then calls may succeed. We assert that either optAddr == address(this) or each attempted call reverted.
        assert(optAddr == address(this) || (reqReverted && resReverted && disReverted));
    }

    receive() external payable {}
}

