contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that fuzzes caller addresses by performing calls from this contract
    // We cannot change msg.sender for calls into c, so we distinguish two scenarios by passing
    // a boolean: if asAsserter==true we simulate the optimistic asserter by querying c.optimisticAsserter(),
    // and then we attempt the protected calls via low-level call with address(this) as sender —
    // but since msg.sender is fixed (this contract) for all calls, we instead check that when
    // c.optimisticAsserter() == address(this) the protected calls do NOT revert, otherwise they revert.
    // We also assert the general rule that the call success equals (c.optimisticAsserter() == address(this)).

    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);

        // Read the optimisticAsserter immutable from c via its public getter
        address asserter = c.optimisticAsserter();

        // Try requestPrice: it's protected by onlyOptimisticAsserter modifier and should revert unless
        // msg.sender == asserter. Here msg.sender is this contract, so success <=> asserter == address(this).
        bool reqReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        // Try assertionResolvedCallback
        bool resReverted;
        try c.assertionResolvedCallback(bytes32(0x123), true) {
            resReverted = false;
        } catch {
            resReverted = true;
        }

        // Try assertionDisputedCallback
        bool disReverted;
        try c.assertionDisputedCallback(bytes32(0x456)) {
            disReverted = false;
        } catch {
            disReverted = true;
        }

        // General rule: each of these calls succeeds iff the optimisticAsserter getter equals address(this)
        bool expectsNoRevert = (asserter == address(this));
        assert((!reqReverted) == expectsNoRevert && (!resReverted) == expectsNoRevert && (!disReverted) == expectsNoRevert);
    }

    // receive to accept any ETH if needed (not used here)
    receive() external payable {}
}

contract InvMutTest {
    C c;
