    // Single public entry that checks the onlyOptimisticAsserter modifier enforcement
    // We take arbitrary inputs that are forwarded to requestPrice; other calls use fixed args.
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);

        // Read the optimisticAsserter immutable from c via its public getter. The getter returns an address typed as OptimisticAsserterInterface,
        // but Solidity auto-generates a function named optimisticAsserter() that returns that type; compare its address.
        address asserterAddr = address(c.optimisticAsserter());

        // Try requestPrice: should revert unless this contract is the optimisticAsserter
        bool reqReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        // Try assertionResolvedCallback with arbitrary values
        bool resReverted;
        try c.assertionResolvedCallback(bytes32(0), true) {
            resReverted = false;
        } catch {
            resReverted = true;
        }

        // Try assertionDisputedCallback with arbitrary value
        bool disReverted;
        try c.assertionDisputedCallback(bytes32(1)) {
            disReverted = false;
        } catch {
            disReverted = true;
        }

        // General rule: none of the three calls reverts iff this contract is the optimisticAsserter; otherwise all revert.
        bool expectNoRevert = (asserterAddr == address(this));
        assert((!reqReverted) == expectNoRevert && (!resReverted) == expectNoRevert && (!disReverted) == expectNoRevert);
    }

    receive() external payable {}
}

