        // a simple payable proxy wallet owned by this contract to forward calls as different senders
        senderProxy = payable(address(uint160(uint256(keccak256(abi.encodePacked(address(this)))))));
    }

    // We cannot actually change msg.sender when calling c from this contract, but the contract C exposes
    // optimisticAsserter immutable; we can observe that onlyOptimisticAsserter allows only that address.
    // The property: if msg.sender equals optimisticAsserter, requestPrice should not revert and should not
    // change address(c).balance (it only emits an event). If caller is not optimisticAsserter it should revert.

    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData, bool callAsOptimisticAsserter) public payable {
        require(true);

        // Read the optimisticAsserter address from c (public immutable getter)
        address optimistic = address(c.optimisticAsserter());

        // Capture c balance before
        uint256 balBefore = address(c).balance;

        bool reverted;
        // If caller should simulate being the optimistic asserter, we require that this contract actually is that address.
        // The checker will deploy c freshly and pass inputs; if this contract is the optimisticAsserter then calling should succeed.
        // Otherwise calling should revert due to onlyOptimisticAsserter.
        if (callAsOptimisticAsserter) {
            // We expect this contract to be the optimisticAsserter for success
            if (address(this) == optimistic) {
                try c.requestPrice(identifier, time, ancillaryData) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // If this contract is not optimisticAsserter, attempting to claim success path should revert; enforce that we observe a revert.
                try c.requestPrice(identifier, time, ancillaryData) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        } else {
            // callAsOptimisticAsserter == false: we expect call to revert unless this contract is optimisticAsserter (which would be odd)
            try c.requestPrice(identifier, time, ancillaryData) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 balAfter = address(c).balance;

        // General rule expressed as a single assert:
        // - If the caller (this contract) equals optimisticAsserter then requestPrice must NOT revert and must NOT change c's balance.
        // - If the caller is not optimisticAsserter then requestPrice MUST revert (due to onlyOptimisticAsserter) OR at least must not transfer Ether into/out of c.
        // We encode this as: (caller==optimistic && !reverted && balAfter==balBefore) || (caller!=optimistic && reverted)
        assert((address(this) == optimistic && reverted == false && balAfter == balBefore) || (address(this) != optimistic && reverted == true));
    }

    // fallback to accept Ether if needed by tests
    receive() external payable {}
}

