    address nonAsserter;

    constructor(C _c) {
        c = _c;
        nonAsserter = address(0x1234);
    }

    // Single public function driving the property check
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        // Prepare: read the optimisticAsserter address from c (public getter)
        address optimistic = address(c.optimisticAsserter());

        // We will attempt three calls that are only permitted to be made by optimisticAsserter.
        // First, calling requestPrice via this contract should revert unless this contract equals optimistic.
        bool requestPriceReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            requestPriceReverted = false;
        } catch {
            requestPriceReverted = true;
        }

        // Second, calling assertionResolvedCallback should revert unless this contract equals optimistic.
        bool resolvedCallbackReverted;
        try c.assertionResolvedCallback(keccak256(abi.encodePacked(identifier, time, ancillaryData)), true) {
            resolvedCallbackReverted = false;
        } catch {
            resolvedCallbackReverted = true;
        }

        // Third, calling assertionDisputedCallback should revert unless this contract equals optimistic.
        bool disputedCallbackReverted;
        try c.assertionDisputedCallback(keccak256(abi.encodePacked(identifier, time, ancillaryData))) {
            disputedCallbackReverted = false;
        } catch {
            disputedCallbackReverted = true;
        }

        // General rule: if this contract is the optimisticAsserter then none of the three calls should revert;
        // otherwise all three must revert due to the onlyOptimisticAsserter modifier.
        assert((address(this) == optimistic && !requestPriceReverted && !resolvedCallbackReverted && !disputedCallbackReverted) ||
               (address(this) != optimistic && requestPriceReverted && resolvedCallbackReverted && disputedCallbackReverted));
    }

    receive() external payable {}
}

